// ❌ Recomposes the whole list on every scroll pixel
@Composable
fun Header(state: LazyListState) {
  val offset = state.firstVisibleItemScrollOffset
  Box(Modifier.offset(y = (-offset / 3).dp)) { Title() }
}

// ✅ Read the state inside a lambda modifier: layout only, no recomposition
@Composable
fun Header(state: LazyListState) {
  Box(Modifier.offset { IntOffset(0, -state.firstVisibleItemScrollOffset / 3) }) { Title() }
}

@Composable
fun Feed(posts: List<Post>) {
  LazyColumn {
    items(posts, key = { it.id }) { post ->      // stable keys, cheap items
      PostRow(post)
    }
  }
}

